@SubscribeEvent
	public static void worldTick(TickEvent.WorldTickEvent event) {
		if (event.phase == TickEvent.Phase.START)
			reversals.removeIf((reversal) -> {
				if (reversal.world.get() == event.world) {
					if (reversal.nemez.hasNext()) {
						reversal.nemez.applySnapshot(event.world);
						if (reversal.pos != null && reversal.world.get().getTotalWorldTime() % PacketNemezReversal.SYNC_AMOUNT == 0)
							PacketHandler.NETWORK.sendToAllAround(new PacketNemezReversal(reversal.nemez),
									new NetworkRegistry.TargetPoint(reversal.world.get().provider.getDimension(),
											reversal.pos.getX() + 0.5, reversal.pos.getY() + 0.5, reversal.pos.getZ() + 0.5, 96));
					} else {
						for (Entity entity : reversal.nemez.getTrackedEntities(event.world))
							entity.setNoGravity(false);
						return true;
					}
				}
				return reversal.world.get() == null;
			});
	}

@SubscribeEvent
	public static void onStun(TickEvent.WorldTickEvent event) {
		if (event.side == Side.CLIENT) return;

		for (EntityFairy fairy : event.world.getEntities(EntityFairy.class, input -> input != null && !input.isDead)) {

			fairy.stunned = false;

			secondary:
			for (EntityPlayer player : event.world.getEntitiesWithinAABB(EntityPlayer.class, fairy.getEntityBoundingBox().grow(5))) {

				for (EnumHand hand : EnumHand.values()) {
					ItemStack stack = player.getHeldItem(hand);

					if (stack.getItem() == ModItems.FAIRY_BELL) {
						fairy.stunned = true;
						break secondary;
					}
				}
			}
		}
	}

@SubscribeEvent
	public void tick(TickEvent.WorldTickEvent event) {
		newEntries.forEach(e -> entityToEntry.put(e.getTarget(), e));
		newEntries.clear();

		entityToEntry.keySet().removeIf(entity -> {
			TrackingEntry entry = entityToEntry.get(entity);
			Entity caster = entry.getCaster();
			int ticks = entry.getTicks();
			double potency = entry.getPotency();
			double duration = entry.getDuration();

			if (ticks > 0) {
				entry.setTicks(ticks - 1);
				return false;
			}

			entity.setFire((int) duration);

			int invTime = entity.hurtResistantTime;
			entity.hurtResistantTime = 0;
			if (caster instanceof EntityPlayer)
				entity.attackEntityFrom(new EntityDamageSource("lightningbolt", caster), (float) potency);
			else entity.attackEntityFrom(DamageSource.LIGHTNING_BOLT, (float) potency);
			entity.hurtResistantTime = invTime;
			return true;
		});
	}

@SubscribeEvent
	public static void vanishTicker(TickEvent.WorldTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		if (event.type != TickEvent.Type.WORLD) return;
		if (event.side != Side.SERVER) return;

		final int sizeAddsBefore = adds.size();
		final int sizeVanishesBefore = vanishes.size();

		for (VanishedObject entry; ((entry = adds.pollFirst()) != null); ) {
			vanishes.add(entry);
		}
		vanishes.removeIf(entry -> {
			if (--entry.tick < 0) {
				Entity e = event.world.getEntityByID(entry.entityID);
				if (e != null && !event.world.isRemote) {
					event.world.playSound(null, e.getPosition(), ModSounds.ETHEREAL_PASS_BY, SoundCategory.NEUTRAL, 0.5f, 1);
				}

				return true;
			}
			return false;
		});

		final int sizeAddsAfter = adds.size();
		final int sizeVanishesAfter = vanishes.size();

		if (!event.world.isRemote && sizeAddsAfter != sizeAddsBefore || sizeVanishesAfter != sizeVanishesBefore) {
			PacketHandler.NETWORK.sendToAll(new PacketSyncVanish(serialize()));
		}
	}

@SubscribeEvent
	public void playerTickPost(TickEvent.PlayerTickEvent event) {
		// this is only relevant for the local player
		if (event.phase == TickEvent.Phase.END && event.player == entityLiving && !event.player.isElytraFlying()) {
			// bounce up. This is to pcircumvent the logic that resets y motion after landing
			if (event.player.ticksExisted == bounceTick) {
				event.player.motionY = bounce;
				bounceTick = 0;
			}

			// preserve motion
			if (!entityLiving.onGround && entityLiving.ticksExisted != bounceTick) {
				if (lastMovX != entityLiving.motionX || lastMovZ != entityLiving.motionZ) {
					double f = 0.91d + 0.025d;
					entityLiving.motionX /= f;
					entityLiving.motionZ /= f;
					entityLiving.isAirBorne = true;
					lastMovX = entityLiving.motionX;
					lastMovZ = entityLiving.motionZ;
				}
			}

			// timing the effect out
			if (wasInAir && entityLiving.onGround) {
				if (timer == 0) {
					timer = entityLiving.ticksExisted;
				} else if (entityLiving.ticksExisted - timer > 5) {
					MinecraftForge.EVENT_BUS.unregister(this);
					bouncingEntities.remove(entityLiving);
				}
			} else {
				timer = 0;
				wasInAir = true;
			}
		}
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void tick(TickEvent.ClientTickEvent event) {
		if (event.phase != TickEvent.Phase.END) return;
		World world = Minecraft.getMinecraft().world;
		if (world == null) return;

		List<EntityUnicorn> unicorns = world.getEntities(EntityUnicorn.class, input -> true);

		for (EntityUnicorn unicorn : unicorns) {
			if (unicorn == null) continue;
			if (unicorn.isDead) {
				positions.remove(unicorn);
				break;
			}

			positions.putIfAbsent(unicorn, new ArrayList<>());

			List<Point> poses = positions.get(unicorn);

			if ((poses.size() >= 1000 || world.getTotalWorldTime() % 20 == 0) && !poses.isEmpty()) {
				poses.remove(0);
			}

			double mot = 0.05;
			if (poses.size() < 1000) {
				if (unicorn.motionX >= mot || unicorn.motionX <= -mot
						|| unicorn.motionY >= mot || unicorn.motionY <= -mot
						|| unicorn.motionZ >= mot || unicorn.motionZ <= -mot) {

					Vec3d backCenter = unicorn.getPositionVector();
					Vec3d look = new Vec3d(unicorn.motionX, unicorn.motionY, unicorn.motionZ).normalize();
					backCenter = backCenter.add(look.scale(-1));

					Vec3d cross = look.crossProduct(new Vec3d(0, 1, 0)).normalize().scale(0.35f);
					poses.add(new Point(backCenter, cross, world.getTotalWorldTime()));
				} else if (!poses.isEmpty()) {
					poses.remove(0);
				}
			}
		}
	}

