@SubscribeEvent
	public static void onFall(LivingFallEvent event) {
		EntityLivingBase entity = event.getEntityLiving();
		if (entity == null) return;

		if (!shouldBounce(entity)) return;

		INSTANCE.blocks.removeIf(bouncyBlock -> entity.world.getTotalWorldTime() - bouncyBlock.tickSpawned > bouncyBlock.expiry);

		boolean isClient = entity.getEntityWorld().isRemote;
		if (event.getDistance() > 0.5) {
			event.setDamageMultiplier(0);
			entity.fallDistance = 0;

			if (isClient) {
				entity.motionY *= -0.9;
				entity.isAirBorne = true;
				entity.onGround = false;
				double f = 0.95;
				entity.motionX /= f;
				entity.motionZ /= f;
				PacketHandler.NETWORK.sendToServer(new PacketBounce());
			} else {
				event.setCanceled(true);
			}
			entity.playSound(SoundEvents.ENTITY_SLIME_SQUISH, 1f, 1f);
			BounceHandler.addBounceHandler(entity, entity.motionY);

		}
	}

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Vec3d position = spell.getTarget(world);
		BlockPos pos = spell.getTargetPos();

		if (position == null || pos == null) return true;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		double area = spellRing.getAttributeValue(world, AttributeRegistry.AREA, spell);

		if (world.getTotalWorldTime() % 2 == 0)
			world.playSound(null, pos, ModSounds.FIZZING_LOOP, CommonProxy.SoundCategory_WizardryGeneral, RandUtil.nextFloat(0.6f, 1f), RandUtil.nextFloat(0.1f, 4f));
		for (Entity entity : world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(new BlockPos(position)).grow(area, area, area))) {
			if (entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				if (potency >= 3) {
					living.addPotionEffect(new PotionEffect(MobEffects.NAUSEA, 100));
				}
				living.addPotionEffect(new PotionEffect(MobEffects.POISON, 60, (int) (potency / 3)));
			}
		}

		return true;
	}

@SubscribeEvent(priority = EventPriority.HIGHEST)
	public void playerTick(TickEvent.PlayerTickEvent event) {
		//Leaving the underowrld
		if (event.player.getEntityWorld().provider.getDimension() == Wizardry.underWorld.getId()) {
			if (event.player.posY < 0) {
				//Gets the players spwanpoint and sets the location to teleport to around that
				event.player.isDead = false;
				BlockPos spawn = event.player.isSpawnForced(0) ? event.player.getBedLocation(0) : event.player.world.getSpawnPoint().add(event.player.world.rand.nextGaussian() * 16, 0, event.player.world.rand.nextGaussian() * 16);
				BlockPos teleportTo = spawn.add(0, 300 - spawn.getY(), 0);
				//stops fall damage
				fallResetter.add(event.player.getUniqueID());
				TeleportUtil.teleportToDimension(event.player, 0, teleportTo.getX(), teleportTo.getY(), teleportTo.getZ());
			}
		}
		//adds pass to check if player on bedrock after reached velocity
		if (event.player.getEntityWorld().provider.getDimension() == 0 && ConfigValues.underworldFallSpeed <= 0) {
			if (event.player.motionY < ConfigValues.underworldFallSpeed || passmap.get(event.player.getEntityId()) != null) {
				passmap.put(event.player.getEntityId(), true);
				BlockPos location = event.player.getPosition();
				BlockPos bedrock = PosUtils.checkNeighborBlocksThoroughly(event.player.getEntityWorld(), location, Blocks.BEDROCK);
				if (bedrock != null) {
					event.player.isDead = false;
					fallResetter.add(event.player.getUniqueID());
					TeleportUtil.teleportToDimension(event.player, Wizardry.underWorld.getId(), 0, 300, 0);
					passmap.remove(event.player.getEntityId());
				} else if (event.player.motionY > ConfigValues.underworldFallSpeed) {//resets pass if stopped falling or slowed down alot
					passmap.remove(event.player.getEntityId());
				}
			}
		}

		if (!event.player.world.isRemote) {
			for (ItemStack stack : event.player.inventory.mainInventory) {
				if (stack.getItem() == ModItems.LEVITATION_ORB) {

					if (stack.getItemDamage() + 1 > stack.getMaxDamage()) {
						stack.shrink(1);
						continue;
					}

					if (event.player.world.getTotalWorldTime() % 10 == 0)
						stack.setItemDamage(stack.getItemDamage() + 1);

					if (!event.player.isPotionActive(ModPotions.LOW_GRAVITY)) {
						event.player.addPotionEffect(new PotionEffect(ModPotions.LOW_GRAVITY, 3, 3, false, false));
					}
					break;
				}
			}
		}
	}

@Override
	public void update() {
		super.update();

		if (getBlockType() == ModBlocks.MANA_BATTERY && !((BlockManaBattery) getBlockType()).testStructure(getWorld(), getPos()).isEmpty())
			return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (getBlockType() != ModBlocks.CREATIVE_MANA_BATTERY) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canSuckFromOutside() || !((TileOrbHolder) tile).canGiveToOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanSuckFromOutside(false);
						((TileOrbHolder) tile).setCanGiveToOutside(true);
						tile.markDirty();
					}
				}
			}


			if (world.getTotalWorldTime() % 20 == 0 && !ManaManager.forObject(getWizardryCap()).isManaFull()) {
				ManaManager.forObject(getWizardryCap())
						.addMana(5)
						.removeBurnout(5)
						.close();

				if (world.isRemote)
					ClientRunnable.run(new ClientRunnable() {
						@Override
						@SideOnly(Side.CLIENT)
						public void runIfClient() {
							Vec3d from = new Vec3d(getPos()).add(0.5, 1, 0.5);
							Vec3d to = from.add(RandUtil.nextDouble(-1, 1), -3, RandUtil.nextDouble(-1, 1));

							ParticleBuilder helix = new ParticleBuilder(200);
							helix.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
							helix.setAlphaFunction(new InterpFloatInOut(0.1f, 0.1f));
							ParticleSpawner.spawn(helix, world, new StaticInterp<>(to), 5, 0, (someFloat, particleBuilder) -> {
								particleBuilder.setColor(ColorUtils.changeColorAlpha(new Color(0x0097FF), RandUtil.nextInt(50, 200)));
								particleBuilder.setScale(RandUtil.nextFloat(0.3f, 0.8f));
								particleBuilder.setPositionFunction(new InterpBezier3D(Vec3d.ZERO,
										from.subtract(to),
										new Vec3d(0, 5, 0), new Vec3d(0, 1, 0)));
								particleBuilder.setLifetime(RandUtil.nextInt(50, 60));
							});
						}
					});
			}

		} else {
			ManaManager.forObject(getWizardryCap())
					.setMana(ManaManager.getMaxMana(getWizardryCap()))
					.setBurnout(0)
					.close();
		}
	}
